DROP TABLE IF EXISTS tbl1; DROP TABLE IF EXISTS tbl2; PRAGMA incremental_vacuum; CREATE TABLE tbl1(a,b); CREATE TABLE tbl2(a,b); BEGIN; WITH RECURSIVE c(i) AS (VALUES(0) UNION ALL SELECT i+1 FROM c WHERE i<999) INSERT INTO tbl1 SELECT i,CAST(i AS TEXT)||CAST(i AS TEXT) FROM c; INSERT INTO tbl2 SELECT * FROM tbl1; COMMIT; DROP TABLE tbl1;